import{_ as l,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2018-12-25","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2018-12-25","date":"2018-12-25T00:00:00.000Z","updated":"2018-12-25T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","连接管理","消息传递机制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-25.md","filePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-25.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-25.md"};function r(n,i,a,g,c,d){return t(),e("div",null,[...i[0]||(i[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年12月25日</p><p><strong>参会人员</strong>： Michael、Rico、Chris、Jim、Lucy、TJ、Piggy、Riddle等</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储中消息传递机制、连接管理、性能优化等问题。</p><p><strong>关键细节</strong>：</p><ul><li><strong>消息传递机制</strong>： <ul><li>Michael在修复回归问题时发现了大量失败，特别是在连接销毁时。</li><li>Rico提出需要修复代码，并隐藏异常。</li><li>Jim强调解决并发消息传递中的bug和异常的重要性。</li><li>Piggy和Riddle讨论了连接引用和数据结构的设计问题。</li></ul></li><li><strong>连接管理</strong>： <ul><li>Michael和Rico讨论了连接跨引用和数据结构的设计。</li><li>Piggy和Riddle讨论了连接引用的共享和修改。</li><li>Rico建议使用socket和输入输出字符串进行调试。</li></ul></li><li><strong>性能优化</strong>： <ul><li>Michael和Rico探讨了使用用户空间调度器的优缺点。</li><li>Piggy和Riddle讨论了单线程和多线程设计的选择。</li><li>Rico提出使用共享无锁设计来提高性能。</li><li>Jim提到使用Nvme设备时的性能优化。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>Michael将继续修复回归问题。</li><li>Rico将继续解决消息传递中的bug和异常。</li><li>Jim将继续调试消息传递机制。</li><li>Piggy和Riddle将继续优化连接管理。</li><li>Riddle将继续研究性能优化方案。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>消息传递机制的设计和优化。</li><li>连接管理的设计和优化。</li><li>性能优化方案的选择。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续修复消息传递和连接管理中的bug。</li><li>优化性能。</li><li>研究单线程和多线程设计的选择。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Michael修复回归问题。</li><li>Rico解决消息传递中的bug。</li><li>Jim调试消息传递机制。</li><li>Piggy和Riddle优化连接管理。</li><li>Riddle研究性能优化方案。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些Ceph相关的关键词，如fulcrum、contest、mentos、shard、object store、OSD、PG、connection、socket等。</li><li>会议中涉及到的技术问题较为复杂，需要进一步研究和讨论。</li></ul>',14)])])}const u=l(s,[["render",r]]);export{p as __pageData,u as default};
